mapper.delete:
DELETE FROM devlog_issues
WHERE devlog_id = #{devlogId}
  AND issue_id = #{issueId}

mapper.select:
SELECT issue_id
FROM devlog_issues
WHERE devlog_id = #{devlogId}

mapper.delete:
DELETE FROM devlog_works
WHERE devlog_id = #{devlogId}
